static void text(int x,int y,const char *s,int size,uint16_t color) {
    while(*s) {
        unsigned c=(unsigned char)*s++,index=0;
        if(c>='0'&&c<='9')index=c-'0'+1;
        if(c>='A'&&c<='Z')index=c-'A'+11;
        if(c==':')index=37;if(c=='/')index=38;if(c=='-')index=39;
        for(int col=0;col<5;col++)for(int row=0;row<7;row++)
            if(font[index][col]&(1u<<row))fm1_lcd_fill_rect((uint32_t)(x+col*size),(uint32_t)(y+row*size),(uint32_t)size,(uint32_t)size,color);
        x+=6*size;
    }
}

static uint16_t scene(int x,int y) {
    unsigned grain=((unsigned)x*1973u+(unsigned)y*9277u)^((unsigned)x*(unsigned)y*26699u);
    int noise=(int)((grain>>3)&3u);
    float dx=(float)x-134.0f,dy=(float)y-122.0f;
    float radius=sqrtf(dx*dx+dy*dy),glow=bound(1.0f-radius/110.0f,0.0f,1.0f);
    int r=7+noise+(int)(8.0f*glow),g=15+noise+(int)(13.0f*glow),b=20+noise+(int)(12.0f*glow);
    if(y>60&&y<175) {
        if(fabsf(radius-64.0f)<0.6f||fabsf(radius-76.0f)<0.5f) {r+=8;g+=13;b+=12;}
        float u=dx*0.66f-dy*0.7513f,v=dx*0.7513f+dy*0.66f;
        float lower=(u+28.0f)*(u+28.0f)/870.0f+v*v/1156.0f;
        float upper=(u+0.0f)*(u+0.0f)/625.0f+v*v/625.0f;
        int body=lower<1.0f||upper<1.0f;
        if(body) {
            float edge=bound(1.0f-fminf(lower,upper),0.0f,1.0f);
            float wood=4.0f*sinf(u*2.8f+v*.3f)+2.0f*sinf(u*6.7f);
            r=(int)(111.0f+62.0f*edge+wood);g=(int)(62.0f+45.0f*edge+wood);b=(int)(28.0f+22.0f*edge);
            if(edge<.07f){r=228;g=182;b=113;}
            float hole=u*u+v*v;
            if(hole<155.0f){r=222;g=177;b=105;}
            if(hole<117.0f){r=38;g=27;b=22;}
            if(hole<88.0f){r=13;g=17;b=19;}
            if(u> -38.0f&&u< -32.0f&&fabsf(v)<13.0f){r=44;g=31;b=23;}
        }
        int neck=u>16.0f&&u<88.0f&&fabsf(v)<6.5f;
        int head=u>87.0f&&u<110.0f&&fabsf(v)<10.0f;
        if(neck||head) {
            r=head?112:37;g=head?64:34;b=head?32:31;
            if(neck&&fabsf(v)>5.3f){r=214;g=169;b=103;}
            if(neck) {
                float fret=fmodf(u-19.0f,8.5f);
                if(fret<.7f){r=150;g=148;b=125;}
                if(fabsf(v)<1.1f&&fmodf(u-23.0f,17.0f)<2.0f){r=205;g=193;b=161;}
            }
            if(head&&fabsf(v)>7.0f&&fmodf(u-87.0f,7.0f)<2.7f){r=188;g=191;b=172;}
        }
        if((body||neck||head)&&u> -36.0f&&u<106.0f&&fabsf(v)<5.3f) {
            float string=fabsf(fmodf(v+5.5f,2.0f)-1.0f);
            if(string<.23f){r=233;g=214;b=164;}
        }
    }
    return rgb(r,g,b);
}

static void draw_static(void) {
    for(unsigned y=0;y<240;y++) {
        for(unsigned x=0;x<240;x++)line_pixels[x]=scene((int)x,(int)y);
        fm1_lcd_blit(0,y,240,1,line_pixels,240);
    }
    text(16,15,"JOSHUA",3,PAPER);text(176,29,"GUITAR",1,CYAN);
    text(17,43,"SAMSHUIJZEN / STRING PORTRAIT",1,GOLD);
    fm1_lcd_fill_rect(16,56,208,1,rgb(45,61,63));
    text(17,65,"SIX STRINGS",1,rgb(123,146,146));
    text(17,163,"PURE",1,CYAN);text(17,172,"SYNTHESIS",1,CYAN);
    fm1_lcd_fill_rect(16,217,208,2,rgb(42,58,60));
    text(16,230,"PLAY  PAUSE   HOME  RESTART",1,rgb(139,160,157));
}

static void draw_wave(void) {
    int values[208];uint32_t head=scope_head,hash=2166136261u;
    for(int x=0;x<208;x++) {
        unsigned k=(unsigned)(x*127/207);
        values[x]=11-(int)scope[(head+k)&127u]*9/32768;
        hash=(hash^(uint32_t)values[x])*16777619u;
    }
    if(hash==last_wave_hash)return;
    last_wave_hash=hash;
    for(int y=0;y<23;y++)for(int x=0;x<208;x++) {
        int distance=y-values[x];if(distance<0)distance=-distance;
        uint16_t color=rgb(10,23+y/5,29+y/6);
        if(y==11)color=rgb(25,43,45);
        if(distance<3)color=rgb(24,70,72);
        if(distance<2)color=CYAN;
        if(distance==0)color=rgb(219,240,219);
        wave_pixels[y*208+x]=color;
    }
    fm1_lcd_blit(16,181,208,23,wave_pixels,208*23);
}

void setup(void) {
    for(int i=0;i<=TABLE;i++)cosine[i]=cosf(TAU*(float)i/(float)TABLE);
    amplitude[0]=0.0f;
    for(int i=1;i<256;i++)amplitude[i]=0.125f*powf(10.0f,(float)(i-255)*(0.375f/20.0f));
    memset(voices,0,sizeof voices);memset((void *)scope,0,sizeof scope);
    memset((void *)meters,0,sizeof meters);memset((void *)pitches,0,sizeof pitches);
    scope_head=0;ui_clock=0;
    memset(led_state,255,sizeof led_state);
    for(unsigned i=0;i<FM1_NKEY;i++)led(i,0);
    led(FM1_BTN_PLAY,1);led(FM1_BTN_HOME,1);led(FM1_BTN_OCT_DOWN,1);led(FM1_BTN_OCT_UP,1);led(FM1_BTN_ARP,1);
    for(int i=0;i<6;i++)old_bars[i]=-1;
    requested_play=1;repeat_piece=0;requested_seek=-1;trim=1.0f;
    clock_frames=0;last_draw=0;last_wave_hash=0;play_gain=1.0f;volume=0.0f;
    last_second=-1;last_play=-1;last_repeat=-1;old_progress=-1;
    seek_to(0);draw_static();
}

void loop(void) {
    uint32_t edges=fm1_input_edges(0);
    if(edges&(1u<<FM1_BTN_PLAY)) {
        if(ui_tick>=LAST_TICK){requested_seek=0;requested_play=1;}
        else requested_play=!requested_play;
    }
    if(edges&(1u<<FM1_BTN_HOME)){requested_seek=0;requested_play=1;}
    if(edges&(1u<<FM1_BTN_ARP))repeat_piece=!repeat_piece;
    int delta=fm1_enc_take(FM1_ENC_SELECT)*100;
    if(edges&(1u<<FM1_BTN_OCT_DOWN))delta-=1002;
    if(edges&(1u<<FM1_BTN_OCT_UP))delta+=1002;
    if(delta)requested_seek=(int32_t)bound((float)((int32_t)ui_tick+delta),0.0f,(float)(LAST_TICK-1));
    int gain=fm1_enc_take(FM1_ENC_KNOB1);
    if(gain)trim=bound(trim+(float)gain*.05f,0.0f,4.0f);
    uint32_t midi;
    while(fm1_midi_take(&midi)) {
        unsigned status=FM1_MIDI_STATUS(midi);
        if(status==0xfau){requested_seek=0;requested_play=1;}
        if(status==0xfbu)requested_play=1;
        if(status==0xfcu)requested_play=0;
    }
    /* LEDs identify sounding modes that fall in the F3..G5 key range. */
    unsigned note_mask=0;
    if(requested_play)for(int i=0;i<6;i++)if(meters[i]>.007f&&pitches[i]>170.0f&&pitches[i]<800.0f) {
        int midi=(int)(69.0f+17.31234049f*logf(pitches[i]/440.0f)+0.5f);
        if(midi>=53&&midi<=79)note_mask|=1u<<(unsigned)(midi-53);
    }
    for(unsigned i=0;i<27;i++)led(FM1_KEY_NOTE0+i,(note_mask>>i)&1u);
    led(FM1_BTN_PLAY,!requested_play||((ui_tick/50u)&1u)==0u);
    led(FM1_BTN_ARP,!repeat_piece||((ui_tick/50u)&1u)==0u);
    uint32_t now=ui_clock;
    if(now-last_draw<4410u && last_play==requested_play && last_repeat==repeat_piece)return;
    last_draw=now;
    int seconds=(int)((ui_tick*TICK_SAMPLES)/FM1_AUDIO_RATE);
    if(seconds>50)seconds=50;
    if(seconds!=last_second||last_play!=requested_play||last_repeat!=repeat_piece) {
        char time[6]={'0',(char)('0'+seconds/60),':',(char)('0'+seconds%60/10),(char)('0'+seconds%10),0};
        fm1_lcd_fill_rect(16,206,208,8,INK);
        text(16,206,time,1,PAPER);text(194,206,"00:50",1,PAPER);
        text(88,206,requested_play?"PLAYING":"PAUSED",1,requested_play?CYAN:GOLD);
        if(repeat_piece)text(141,206,"R",1,GOLD);
        last_second=seconds;last_play=requested_play;last_repeat=repeat_piece;
    }
    int progress=(int)(ui_tick*208u/LAST_TICK);
    if(progress!=old_progress) {
        fm1_lcd_fill_rect(16,217,208,2,rgb(42,58,60));
        if(progress)fm1_lcd_fill_rect(16,217,(uint32_t)progress,2,GOLD);
        old_progress=progress;
    }
    for(int i=0;i<6;i++) {
        int height=(int)bound(meters[i]*1300.0f,0.0f,64.0f);
        if(!requested_play)height=0;
        if(height!=old_bars[i]) {
            fm1_lcd_fill_rect((uint32_t)(18+i*6),88,3,65,INK);
            if(height)fm1_lcd_fill_rect((uint32_t)(18+i*6),(uint32_t)(153-height),3,(uint32_t)height,i<3?GOLD:CYAN);
            old_bars[i]=height;
        }
    }
    draw_wave();
}
